'use strict';
const C=window.LifelineAssetCore,KEY=new URLSearchParams(location.search).has('life')?'lifeline-art-v1:'+String(Number(new URLSearchParams(location.search).get('life'))>>>0):'LifelineAssetPilot:v1';
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');
let manifest,catalog,state,revision=0,art;
const image=(...args)=>art.image(...args),colored=(...args)=>art.colored(...args),makeActor=(id,a)=>art.actor(id,C.resolveExpression(a)),geometry=(...args)=>art.geometry(...args);
async function render(){const serial=++revision,s=C.copy(state),draws=[];const bg=await image(manifest.scene.background);for(const id of C.visibleIds(s)){const a=s.actors[id];draws.push({im:await makeActor(id,a),...geometry(id,a)});}if(s.dogVisible){const selected=C.companionSelection(manifest,s,s.petKind),im=await art.companion(selected);draws.push({im,...C.companionGeometry(manifest,selected)});}if(serial!==revision)return;ctx.setTransform(3,0,0,3,0,0);ctx.clearRect(0,0,320,320);ctx.drawImage(bg,0,0,320,320);for(const item of draws.sort((a,b)=>a.footY-b.footY))ctx.drawImage(item.im,item.x,item.y,item.im.width*item.scale,item.im.height*item.scale);
if($('debug').checked){ctx.save();for(const poly of manifest.scene.walkableAreas){ctx.beginPath();poly.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle='#72b89255';ctx.fill();ctx.strokeStyle='#297449';ctx.lineWidth=.8;ctx.stroke();}for(const slot of manifest.scene.slots){ctx.beginPath();ctx.arc(...slot.position,4,0,Math.PI*2);ctx.fillStyle='#db9167';ctx.fill();ctx.fillStyle='#493a30';ctx.font='6px sans-serif';ctx.fillText(slot.id,slot.position[0]-12,slot.position[1]-7);}ctx.restore();}
const renderedPet=s.dogVisible?C.companionSelection(manifest,s,s.petKind):null;for(const [key,value]of Object.entries({petKind:renderedPet?.kind||'none',petVariant:renderedPet?.variant||'',petAge:renderedPet?.age||'',petPose:renderedPet?.pose||'',petColor:renderedPet?.color??0}))canvas.dataset[key]=String(value);$('actor-label').textContent=C.LABELS[s.activeId]+' · '+(s.actors[s.activeId].pose==='sitting'?'сидит':'стоит');window.pilotLastRender={serial,visible:C.visibleIds(s),drawCount:draws.length};}
function notice(text){$('notice').textContent=text;}
function persist(){localStorage.setItem(KEY,JSON.stringify(state));}
function update(){persist();sync();render().catch(e=>notice(e.message));renderMix();}
function fill(id,items){$(id).replaceChildren(...items.map(([value,text])=>{const o=document.createElement('option');o.value=value;o.textContent=text;return o;}));}
function sync(){const a=state.actors[state.activeId];const names={short:'Короткая',bob:'Каре',none:'Без волос'};fill('hairStyle',C.availableHairStyles(state.activeId).map(id=>[id,names[id]]));$('actor').value=state.activeId;for(const id of ['skin','hairStyle','hairColor','head','mouth','top','bottom'])$(id).value=a[id];$('mouthMode').value=a.mouthMode;$('mouth').disabled=a.mouthMode==='auto';$('mouth').value=C.resolveExpression(a).mouth;$('happiness').value=a.happiness;$('happiness-value').textContent=Math.round(a.happiness)+'%';$('fatigue').value=Math.round(a.fatigue*100);$('fatigue-value').textContent=Math.round(a.fatigue*100)+'%';$('show-all').checked=state.showAll;$('dog-visible').checked=state.dogVisible;const kind=state.petKind,def=manifest.pets[kind],selected=C.companionSelection(manifest,state,kind);$('pet-kind').value=kind;fill('dog-breed',kind==='dog'?Object.entries(C.DOG_BREEDS):Object.entries(def.variants).map(([key,v])=>[key,v.label]));fill('dog-age',kind==='dog'?[['puppy','Щенок'],['adult','Взрослая'],['senior','Пожилая']]:Object.entries(def.ageLabels));fill('dog-pose',kind==='dog'?Object.entries(C.DOG_POSES).filter(([key])=>state.dogBreed!=='prototype'||['standing','sitting'].includes(key)):Object.entries(def.poseLabels));fill('dog-color',(kind==='dog'?['Исходный','Коричневый','Светлый']:def.colorLabels).map((label,i)=>[i,label]));$('dog-breed').value=selected.variant;$('dog-age').value=selected.age;$('dog-pose').value=selected.pose;$('dog-color').value=selected.color;$('house-seed').value=state.houseSeed;}
function change(key,value){if(key==='hairStyle')value=C.playerHairStyle(state.activeId,value);state.actors[state.activeId][key]=value;if(['happiness','fatigue'].includes(key))state.actors[state.activeId].mouthMode='auto';notice('Слои обновлены. Личность и остальные жители сохранены.');update();}
function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function renderMix(){const available=new Set(catalog.map(x=>x.id));if(!state.houseRooms||Object.values(state.houseRooms.rooms||{}).some(id=>!available.has(id)))state.houseRooms=C.mixRooms(state.houseSeed,catalog,'village_low_pilot');const container=$('room-previews');container.replaceChildren();for(const kind of ['kitchen','bedroom','bathroom']){const item=catalog.find(x=>x.id===state.houseRooms.rooms[kind]);const figure=document.createElement('figure'),im=document.createElement('img'),cap=document.createElement('figcaption');im.src=item.path;im.alt=item.label;cap.textContent=item.label;figure.append(im,cap);container.append(figure);}$('house-json').textContent=JSON.stringify(state.houseRooms,null,2);}
async function init(){[manifest,catalog]=await Promise.all([fetch('manifest.json?v=12').then(r=>r.json()),fetch('room_catalog.json').then(r=>r.json())]);art=LifelinePngRenderer.create(manifest);state=C.defaultState();try{const saved=localStorage.getItem(KEY);if(saved)state=C.validateState(JSON.parse(saved),manifest);}catch(e){notice('Сохранение пилота не загружено: '+e.message);}if(new URLSearchParams(location.search).has('month'))state=C.petStateAt(state,Number(new URLSearchParams(location.search).get('month')));fill('actor',C.PROFILES.map(id=>[id,C.LABELS[id]]));fill('skin',manifest.palettes.skin.map((c,i)=>[i,'Тон '+(i+1)]));fill('hairColor',['Тёмно-каштановый','Почти чёрный','Рыжий','Седой','Светлый'].map((x,i)=>[i,x]));fill('top',['Мох','Терракота','Голубой','Сиреневый'].map((x,i)=>[i,x]));fill('bottom',['Тёмно-синий','Графит','Коричневый'].map((x,i)=>[i,x]));fill('pet-kind',[['dog','Собака'],...Object.entries(C.PET_TYPES).filter(([key])=>manifest.pets[key]?.available)]);fill('dog-breed',Object.entries(C.DOG_BREEDS));fill('dog-color',['Исходный рыжий','Коричневый','Светлый'].map((x,i)=>[i,x]));
$('actor').onchange=e=>{state.activeId=e.target.value;update();};for(const id of ['skin','hairColor','top','bottom'])$(id).onchange=e=>change(id,Number(e.target.value));for(const id of ['hairStyle','head','mouth','mouthMode'])$(id).onchange=e=>change(id,e.target.value);$('happiness').oninput=e=>change('happiness',Number(e.target.value));$('fatigue').oninput=e=>change('fatigue',Number(e.target.value)/100);
$('stand').onclick=()=>{const a=state.actors[state.activeId];a.pose='standing';a.seatId=null;notice('Стоячая поза.');update();};for(const [button,slot] of [['seat-left','sofa_left'],['seat-right','sofa_right']])$(button).onclick=()=>{const result=C.sit(state,state.activeId,slot,manifest);if(result.ok){state=result.state;notice('Статичная сидячая поза совмещена с местом.');update();}else notice(result.error);};
$('show-all').onchange=e=>{state=e.target.checked?C.showAll(state,manifest):{...state,showAll:false};update();};$('dog-visible').onchange=e=>{state.dogVisible=e.target.checked;update();};$('pet-kind').onchange=e=>{state.petKind=e.target.value;update();};for(const [id,field] of Object.entries({'dog-breed':'variant','dog-age':'age','dog-pose':'pose','dog-color':'color'}))$(id).onchange=e=>{C.setCompanion(state,state.petKind,field,field==='color'?Number(e.target.value):e.target.value,Number(new URLSearchParams(location.search).get('month'))||0,manifest);update();};$('debug').onchange=()=>render();
canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),p=[(e.clientX-r.left)*320/r.width,(e.clientY-r.top)*320/r.height];const result=C.move(state,state.activeId,p,manifest);if(result.ok){state=result.state;notice('Фигура переставлена. Цикл ходьбы ещё не реализован.');update();}else notice(result.error);};
$('save').onclick=()=>download('lifeline-pilot-state.json',new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));$('png').onclick=async()=>{const out=await makeActor(state.activeId,state.actors[state.activeId]);out.toBlob(blob=>download('lifeline-'+state.activeId+'-'+state.actors[state.activeId].pose+'.png',blob));};$('dog-png').onclick=async()=>{const selected=C.companionSelection(manifest,state,state.petKind),out=await art.companion(selected);if(out.toBlob)out.toBlob(blob=>download('lifeline-'+selected.kind+'-'+selected.variant+'-'+selected.age+'-'+selected.pose+'-'+selected.color+'.png',blob));else{const temp=document.createElement('canvas');temp.width=out.width;temp.height=out.height;temp.getContext('2d').drawImage(out,0,0);temp.toBlob(blob=>download('lifeline-'+selected.kind+'-'+selected.variant+'-'+selected.age+'-'+selected.pose+'-'+selected.color+'.png',blob));}};$('scene-png').onclick=()=>canvas.toBlob(blob=>download('lifeline-scene-pilot.png',blob));
$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;state=C.validateState(JSON.parse(await file.text()),manifest);notice('Комбинация загружена.');update();}catch(err){notice('Не удалось загрузить: '+err.message);}finally{e.target.value='';}};
$('mix').onclick=()=>{const n=Number($('house-seed').value);if(!Number.isInteger(n)||n<1){notice('Введите целый номер от 1.');return;}state.houseSeed=n>>>0;state.houseRooms=C.mixRooms(state.houseSeed,catalog,'village_low_pilot');notice('Набор комнат сохранён за домом.');update();};
window.LifelinePilot={manifest,catalog,getState:()=>C.copy(state),setState:async input=>{state=C.validateState(input,manifest);persist();sync();renderMix();await render();},render,makeActor,storageKey:KEY};const requested=new URLSearchParams(location.search).get('profile');if(C.PROFILES.includes(requested))state.activeId=requested;sync();renderMix();persist();await render();notice('Готово. Меняйте внешность, позы и комбинации комнат.');return true;}
window.pilotReady=init().catch(e=>{notice('Ошибка загрузки: '+e.message+'. Запустите локальный сервер по README.');throw e;});
